import React, { useState } from 'react';
import { Users, Ban, CheckCircle, Search } from 'lucide-react';

export default function Customers() {
  const [customers, setCustomers] = useState([
    { id: 1, name: 'Tanvir Ahmed', phone: '01711223344', totalOrders: 14, cancelled: 1, isBlocked: false },
    { id: 2, name: 'Fake Account User', phone: '01999887766', totalOrders: 3, cancelled: 3, isBlocked: true },
  ]);

  const toggleBlock = (id) => {
    setCustomers(customers.map(c => c.id === id ? { ...c, isBlocked: !c.isBlocked } : c));
  };

  return (
    <div className="p-8 space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-2xl font-black text-gray-900">Customer Control & Fraud Check</h1>
          <p className="text-sm text-gray-500">অর্ডার হিস্ট্রি চেক করুন এবং ফেক ইউজারদের ব্যান করুন</p>
        </div>
      </div>

      <div className="bg-white rounded-2xl border border-gray-100 shadow-sm overflow-hidden">
        <div className="divide-y divide-gray-100">
          {customers.map((c) => (
            <div key={c.id} className="p-4 flex items-center justify-between">
              <div>
                <h4 className="font-bold text-gray-900">{c.name}</h4>
                <p className="text-xs text-gray-500">{c.phone}</p>
                <div className="flex gap-3 text-xs mt-1">
                  <span className="text-emerald-700 font-semibold">Delivered: {c.totalOrders - c.cancelled}</span>
                  <span className="text-red-600 font-semibold">Cancelled: {c.cancelled}</span>
                </div>
              </div>

              <button
                onClick={() => toggleBlock(c.id)}
                className={`flex items-center gap-1.5 px-4 py-2 rounded-xl text-xs font-bold transition-all ${
                  c.isBlocked ? 'bg-gray-100 text-gray-700 hover:bg-gray-200' : 'bg-red-50 text-red-600 hover:bg-red-100'
                }`}
              >
                <Ban className="w-3.5 h-3.5" />
                {c.isBlocked ? 'Unblock Customer' : 'Block / Ban User'}
              </button>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}
